      "eventuallydiscoveredthenoticeboardbychance. PASSAGE II Tolisten properly is hard job, and probably one of the toughest skills in the art of communication. Good listening has nothing to do with proper functioning of one’s auditoryorgans, which is assumed to be inevitable. Good listening in the sense weare interested in, is not a biological factor, but a psychological one. Yourauditory organs maybe in perfect order, when actually, you cannot use them creatively. Creative listening implies your being efficient, in the art of concentration, in other words, you concentrate on what one is saying so as to make sure that you hear all that is said. At the same time you are concentrating to hear all that is being said, you are also thinking fast, digesting what is being said, allowing your mental faculties and your memoryto accept that which you understand, and to reject that which you do not understand, sorting out what you do not understand and storing them somewhere in your brain for future discussion, and, all at the same time, rationalizing what youher, accepting that which you find rational and rejecting that which youdo not find rational. After you must have listened creatively to what you have been told, then you can respond if the need arises. It is quite proper that you respond because the process of response enhances the art of communication. But your response ought to be only a necessary response, a response that will improve your understanding. This response should involve your monitoring, some of those things you have been told but which you do not understand, or politely questioning the rationality of some of the speakers argument that your response must be constructive, must enhance thecommunicativeworth. It should not be an unnecessary argument or an opportunity for you to express dissatisfaction or disaffection. The ability to listen properly aidscommunication and understanding."
