      "One produces amplified sounds, the other does not. PASSAGE II The preparation which a study of the humanities can provide, stems from three observations about education in our world of accelerating social and technological change. First, with the rate of change, we cannot hope to train our students for specific technologies. That kind of vocational education is obsolescent. By the time the specific training will have been completed the world will have moved on. Ifour educationofnarrowtraining, wewillnot beprepared to change. Second, and paradoxically, what our students desire fromtheir education is preparation for specificcareers, – business, engineering, medicine, computer programming and the like, but we will not be able to train them for a life-long career. Their confrontingthedepressed jobmarketgivesour students acertain anxiety, but the solution they seek in vocation training is not sufficient. Third, we sense in our students a narrowing materialism, with the good life defined in terms of material comforts. Education, then meanslearning to do a jobwhich will make money. I see in this definition a limiting sense of what education and thus life offer, a definition which excludes joy and meaning. Our approach to the study of the humanities responds to these three related problems. In our changing, yet narrowing world, the teaching of the humanities finds one powerful justification – it teaches students how to think."
