      "a prominentstatistician",
      "a professor of statistics. PASSAGE V All too often, there is a difference between what we say and what we think we have said, and between how we feel we have handled people and how they think the have been treated. When such ‘gaps’ occur between the intent and the action, it is often stated that there has been ‘a breakdown in communication’. Sometimes, the break-down is allowed to become so serious that the gap becomes a chasm, relatives in a family ceasing to speak to one another, management and trade unions refusing to meet, or governments recalling ambassadors when relations between states reach a low ebb. In fact, sometimeswhen peoplecommunicate, either as individual or within groups, problems inevitably occur; instructions may be impossible to carry out, offence is taken at a particular remark, a directiveisambiguouslyphrased or people’s attitudes are coloured by jealousy, resentment or frustration. During the past fiftyyears, industrial, commercial and public service organizations have grown prodigiously to meet the needs of advanced technological societies. Sometimes as manyas 10,000 peopleworkon thesite,or one companyemploys more than 50,000 people. Clearly, good communications are essential to the efficient operations of any organization, and vitalto thefulfillment ofall thosewhocommit their workinglives toit. For this reason, management specialists and behavioural scientists have devoted much thought and energy over recent years to analyzing the problems caused by bad communication practices, and to creating good communication climate and systems. As a result of the current structure of societies and economies, most ofus will spend our working lives in an organization – for many of us it will be a large one. If we are to understand our working environment, it is essential that we become good communicators with socialskills."
