      "domineering. PASSAGE II Theatre in the recent past used tobe a very popular art in traditional African society. It used tobea point ofintersection where members of the community not only come to entertain themselves, but ‘join heads together’. In the traditional context African drama therefore, Theatre was a popular and respectable institution, which preserved the people’s culture and tradition. Theatre was popular with the people because it emphasized communityparticipation, peaceand progress. The presentations focused on the people’s lives, their aspirations, fears andhopes. But today, the situation is different. Theatre is becoming very unpopular. Africa of the present age is pre-occupied with many problems yearning for immediate solutions. The continent is facing hydra-headed challenges --- challenges on the political, social and economic scenes. In a world where science and technology are seen as the solutions to these problems, little attention is paid to the arts. Literature generally, and drama in particular, is often rated very low on the utility scale. Many in Africa todaylook at drama and theatre as a mere thing offun, a joke so to say. Elitism is another barrier that militates against the appreciation of theatre as a communal art. Folk theatre is appreciated by a negligible number of people. Contemporary focus is on literary theatre. Unfortunately. Literary theatre only pretends to serve the interest ofits societywhile in reality it has aforeign audiencein mind. Theuseof Europeans and American theatrical conventions by our academic playwrights can bear witness to thisanomaly. The popularity of the literary African theatre is further marred bythe mediumofcommunication as mostliterarydramas in Africa are written in foreign languages, which are not understood by many Africans. The question often asked is whether the artist should climb down to the level of his community or stay at his exalted height and wait for the communitytograduallymoveup tohim."
