      "was certain about the Eagles’ chances. This shocking defeat of France had raised Africa’s hopes of going beyond the first round of the tournament. So when the Super Eagles of Nigeria filed out against Argentina on the morning of Sunday, June the second, 2002, many Nigerian football enthusiasts delayed attending church service to watch the match live on television. As expected, the Super Eagles put up strong resistance to the Argentinian challenge and the day would not have ended on a somber note for Nigerians if the momentum had been sustained throughout the match. The hope of going beyond the first round, though precarious, was verymuch alive as the Eagles were expected to defeat their next opponents, Sweden and England. But some shortcomingsin the Nigerian national team needed toberectified to brighten their chances against their next opponents. First, the defence needed to bestrengthened to prevent the opponents from incessantlyterrorizing the goalkeeper. Then thestrikersalsoneededtoimproveon their lacklusterperformance against Argentina, since every Nigerian expected them to overwhelm their next opponents in the opening rounds. Lastly, rather than gamble with unfit players, a morecreativeuse ofthe reserves would be necessary to smooth the way to the next round. If World Cup debutants, Senegal ,could nurse the hope of playing in the knock-out stages of the tournament, then the PASSAGE III Attitudes towards the smoking of cigarettes and the consumption ofalcohol maybe used to illustrate typical African ethics. Apart from the fact that smoking has now been linked with lung cancer disease, the African moralist has always regarded smoking as an indication of moral degradation. A number of people have accepted the moralist idea on smoking. Some have refrained from smoking, and those who could influence others, such as parents and religious leaders, have alsoexerted their influence to prevent others from smoking. On the other hand, a good many people have remained indifferent to the moralist view and have continued to smoke. The same argument has been applied to the consumption of alcohol. The African moralist, basing his judgement on the behaviour of a few alcoholics, tends to regard the habit of taking alcohol as a sign of wretchedness. The moralist holds the viewthat anybody who forms the habit ofconsuming alcohol will never do well in live. While this may be true in respect of a few people in the society, the fear of the moralist has not been justified. However, the economicsisprimarilyinterested in thehabit of smoking and the consumption of alcohol in so far as they give satisfaction to smokers and drinkers and so generate supplyofand demand for tobacco and alcohol. The economist is interested in knowing howmany packets ofcigarettes are consumedandto what extent an increase or fall in consumption could affect production, that is, supply. Similarly, he is interested in how much beer is consumed and howthe supplyof beer will adjust to the demand for it. He examines the habits and the pressures which can lead to the readjustment of wants and the reallocation of resources to cover the wants. Some moral principles associated with religion tend to lead on toeconomic problems. Followersof certain religionsare expected not to consume pork, take alcohol or smoke tobacco. Devotees of some religious groups, on the other hand, can eat pork while others are expected to abstain from alcohol and smoking. Strict observance of these moral rules could cripple the breweries, the cigarette factories and some businesses. However, there seems to be a growing number of alcohol consumersand cigarette smokers – a development which should be of interest to the economist."
